[CmdletBinding()]
param([string]$EvidenceDirectory)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$scriptPath=Join-Path $root 'scripts/New-CiCostInput.ps1';$base=if($EvidenceDirectory){[IO.Path]::GetFullPath($EvidenceDirectory)}else{Join-Path ([IO.Path]::GetTempPath())('ci-cost-input-'+[guid]::NewGuid().ToString('N'))};if(Test-Path $base){throw 'Evidence directory must be new.'};$null=New-Item -ItemType Directory $base
function WriteJ([string]$p,$v){[IO.File]::WriteAllText((Join-Path $base $p),($v|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))}
function InvokeInput([int]$Expected=0){$out=Join-Path $base 'cost-input.json';$text=& pwsh -NoProfile -File $scriptPath -EvidenceDirectory $base -RunId 'run-中文' -CodeIdentity 'candidate-a' -TaskExitCode 0 -TaskWallClockMs 1234 -OutputPath $out 2>&1;if($LASTEXITCODE -ne $Expected){throw "expected $Expected got ${LASTEXITCODE}: $($text -join ' ')"};if($Expected -eq 0){return Get-Content $out -Raw|ConvertFrom-Json -Depth 30}}
$trxDir=Join-Path $base 'results';$null=New-Item -ItemType Directory $trxDir;$trx=Join-Path $trxDir 'one.trx';[IO.File]::WriteAllText($trx,'fixture',[Text.UTF8Encoding]::new($false))
$test=[ordered]@{command='dotnet';arguments=@('test','project.csproj','--logger','trx;LogFileName=one.trx','--results-directory','results');log='test.log';phase='completed';exitKnown=$true;rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitCode=0;expectedExit=0}
$discover=[ordered]@{command='dotnet';arguments=@('test','project.csproj','--list-tests');log='discover.log';phase='completed';exitKnown=$true;rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitCode=0;expectedExit=0}
$restore=[ordered]@{command='dotnet';arguments=@('restore','project.sln');log='restore.log';phase='completed';exitKnown=$true;rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitCode=1;expectedExit=1}
$build=[ordered]@{command='dotnet';arguments=@('build','project.sln','--no-restore');log='build.log';phase='completed';exitKnown=$true;rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitCode=1;expectedExit=1}
$lookalike=[ordered]@{command='dotnet';arguments=@('restore-extra','project.sln');log='lookalike.log';phase='completed';exitKnown=$true;rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitCode=0;expectedExit=0}
$legacyDiscover=[ordered]@{command='custom-runner';arguments=@('--list-tests');log='legacy-discover.log';phase='completed';exitKnown=$true;rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitCode=0;expectedExit=0}
WriteJ 'commands.json' @($test,$discover,$restore,$build,$lookalike,$legacyDiscover);$report=InvokeInput; if($report.selections[0].category-ne'test' -or $report.selections[0].trx.Count-ne1 -or $report.selections[1].category-ne'discovery' -or $report.selections[2].category-ne'restore' -or $report.selections[3].category-ne'build' -or $report.selections[4].category-ne'other' -or $report.selections[5].category-ne'discovery' -or $report.task.completion-ne'completed'){throw 'valid command mapping incorrect'}
Remove-Item (Join-Path $base 'cost-input.json') -ErrorAction SilentlyContinue;WriteJ 'commands.json' @();InvokeInput 1
Remove-Item (Join-Path $base 'cost-input.json') -ErrorAction SilentlyContinue;WriteJ 'commands.json' @($test,$test);InvokeInput 1
Remove-Item (Join-Path $base 'cost-input.json') -ErrorAction SilentlyContinue;$bad=$test|ConvertTo-Json|ConvertFrom-Json -AsHashtable;$bad.arguments=@('test','project.csproj','--results-directory','missing');WriteJ 'commands.json' @($bad);InvokeInput 1
# An external index must retain absolute bindings to the original evidence root.
Remove-Item (Join-Path $base 'cost-input.json') -ErrorAction SilentlyContinue
$external=Join-Path (Split-Path $base -Parent) ('ci-cost-index-'+[guid]::NewGuid().ToString('N')+'.json')
WriteJ 'commands.json' @($test);$externalReport=(& pwsh -NoProfile -File $scriptPath -EvidenceDirectory $base -RunId 'external-index' -CodeIdentity 'candidate-a' -TaskExitCode 0 -TaskWallClockMs 1234 -OutputPath $external 2>&1);if($LASTEXITCODE -ne 0){throw "external output failed: $($externalReport -join ' ')"};$externalJson=Get-Content $external -Raw|ConvertFrom-Json -Depth 30;if($externalJson.commandsPath -ne (Join-Path $base 'commands.json')){throw 'External index lost original commands root.'};if(-not [IO.Path]::IsPathRooted([string]$externalJson.selections[0].trx[0].path)){throw 'External index TRX binding is not absolute.'};$before=[IO.File]::ReadAllBytes($external);$again=& pwsh -NoProfile -File $scriptPath -EvidenceDirectory $base -RunId 'external-index' -CodeIdentity 'candidate-a' -TaskExitCode 0 -TaskWallClockMs 1234 -OutputPath $external 2>&1;if($LASTEXITCODE -ne 1){throw 'Existing output was overwritten.'};if(-not [Convert]::ToBase64String($before).Equals([Convert]::ToBase64String([IO.File]::ReadAllBytes($external)))){throw 'Existing output changed after overwrite rejection.'};Remove-Item $external -Force
# Results outside the owned root are rejected even when the CLI argument is rooted.
Remove-Item (Join-Path $base 'cost-input.json') -ErrorAction SilentlyContinue;$escape=$test|ConvertTo-Json|ConvertFrom-Json -AsHashtable;$escape.arguments=@('test','project.csproj','--logger','trx;LogFileName=one.trx','--results-directory',[IO.Path]::GetTempPath());WriteJ 'commands.json' @($escape);InvokeInput 1
Write-Output 'PASS CiCostInput regression: rooted/relative current TRX mapping, external index binding, discovery distinction, empty/duplicate/missing/escape/no-overwrite failures.'
if(-not$EvidenceDirectory){Remove-Item $base -Recurse -Force}
